(ns episodes.index-spec
  (:require [speclj.core :refer :all]
            [gherclj.core :as g]
            [gherclj.lifecycle :as lifecycle]
            [isaac.config.config-steps :as config-steps]
            [isaac.episodes.episode-steps :as episode-steps]
            [isaac.foundation.cli-steps :as cli-steps]
            [isaac.foundation.fs-steps :as fs-steps]
            [isaac.foundation.root-steps :as root-steps]))

(describe "Episodes — index"

  (around [it]
    (binding [g/*state* (atom {})]
      (lifecycle/run-before-feature-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-feature-hooks!)))))

  (around [it]
    (binding [g/*state* (atom @g/*state*)]
      (lifecycle/run-before-scenario-hooks!)
      (try
        (it)
        (finally
          (lifecycle/run-after-scenario-hooks!)))))

  (it "index subcommand is registered and has help"
    ;; Given an Isaac root at "isaac-state"  (episodes/index.feature:12)
    (g/with-step* "Given an Isaac root at \"isaac-state\"" "episodes/index.feature" 12 (fn [] (isaac.foundation.root-steps/in-memory-state "\"isaac-state\"")))
    ;; And the isaac EDN file "config/providers/grover.edn" exists with:  (episodes/index.feature:13)
    ;;   | path | value |  (episodes/index.feature:14)
    ;;   | api | grover |  (episodes/index.feature:15)
    ;;   | auth | none |  (episodes/index.feature:16)
    (g/with-step* "And the isaac EDN file \"config/providers/grover.edn\" exists with:" "episodes/index.feature" 13 (fn [] (isaac.foundation.fs-steps/isaac-edn-file-exists "config/providers/grover.edn" {:headers ["path" "value"], :rows [["api" "grover"] ["auth" "none"]], :header-line 14, :row-lines [15 16]})))
    ;; When isaac is run with "help episodes"  (episodes/index.feature:21)
    (g/with-step* "When isaac is run with \"help episodes\"" "episodes/index.feature" 21 (fn [] (isaac.foundation.cli-steps/isaac-run "help episodes")))
    ;; Then the stdout matches:  (episodes/index.feature:22)
    ;;   | pattern |  (episodes/index.feature:23)
    ;;   | Usage: isaac episodes \[subcommand\] \[options\] |  (episodes/index.feature:24)
    ;;   | migrate-session <session-id>\s+Materialize a session as a closed episode |  (episodes/index.feature:25)
    ;;   | index\s+Embed sealed scenes into the per-crew retrieval index |  (episodes/index.feature:26)
    (g/with-step* "Then the stdout matches:" "episodes/index.feature" 22 (fn [] (isaac.foundation.cli-steps/stdout-matches {:headers ["pattern"], :rows [["Usage: isaac episodes \\[subcommand\\] \\[options\\]"] ["migrate-session <session-id>\\s+Materialize a session as a closed episode"] ["index\\s+Embed sealed scenes into the per-crew retrieval index"]], :header-line 23, :row-lines [24 25 26]})))
    ;; And the exit code is 0  (episodes/index.feature:27)
    (g/with-step* "And the exit code is 0" "episodes/index.feature" 27 (fn [] (isaac.foundation.cli-steps/exit-code-is "0"))))

  (it "indexing a crew embeds gist and text rows per scene"
    ;; Given an Isaac root at "isaac-state"  (episodes/index.feature:12)
