    ;; Given config file "isaac.edn" containing:  (episodes/index.feature:34)
    (g/with-step* "Given config file \"isaac.edn\" containing:" "episodes/index.feature" 34 (fn [] (isaac.config.config-steps/config-file-containing "isaac.edn" "{:embedding {:source :provider :provider \"grover\" :model \"mini-embed\"}}")))
    ;; And crew "cordelia" has a closed episode "2026-03-01-1000-ab12" with scenes:  (episodes/index.feature:38)
    ;;   | id | started-at | ended-at | gist | text |  (episodes/index.feature:39)
    ;;   | 2026-03-01-1000-s1x1 | 2026-03-01T10:00:00 | 2026-03-01T10:05:00 | wine | pinot |  (episodes/index.feature:40)
    ;;   | 2026-03-01-1006-s2x2 | 2026-03-01T10:06:00 | 2026-03-01T10:09:00 | race | dawn |  (episodes/index.feature:41)
    (g/with-step* "And crew \"cordelia\" has a closed episode \"2026-03-01-1000-ab12\" with scenes:" "episodes/index.feature" 38 (fn [] (isaac.episodes.episode-steps/crew-has-closed-episode-with-scenes "cordelia" "2026-03-01-1000-ab12" {:headers ["id" "started-at" "ended-at" "gist" "text"], :rows [["2026-03-01-1000-s1x1" "2026-03-01T10:00:00" "2026-03-01T10:05:00" "wine" "pinot"] ["2026-03-01-1006-s2x2" "2026-03-01T10:06:00" "2026-03-01T10:09:00" "race" "dawn"]], :header-line 39, :row-lines [40 41]})))
    ;; When isaac is run with "episodes index --crew cordelia"  (episodes/index.feature:42)
    (g/with-step* "When isaac is run with \"episodes index --crew cordelia\"" "episodes/index.feature" 42 (fn [] (isaac.foundation.cli-steps/isaac-run "episodes index --crew cordelia")))
    ;; Then the stdout contains "4 new rows"  (episodes/index.feature:43)
    (g/with-step* "Then the stdout contains \"4 new rows\"" "episodes/index.feature" 43 (fn [] (isaac.foundation.cli-steps/stdout-contains "4 new rows")))
    ;; And the exit code is 0  (episodes/index.feature:44)
    (g/with-step* "And the exit code is 0" "episodes/index.feature" 44 (fn [] (isaac.foundation.cli-steps/exit-code-is "0")))
    ;; And the index for crew "cordelia" has rows:  (episodes/index.feature:45)
    ;;   | episode-id | scene-id | kind | model | vector |  (episodes/index.feature:46)
    ;;   | 2026-03-01-1000-ab12 | 2026-03-01-1000-s1x1 | gist | mini-embed | [4 435 119 101] |  (episodes/index.feature:47)
    ;;   | 2026-03-01-1000-ab12 | 2026-03-01-1000-s1x1 | text | mini-embed | [5 554 112 116] |  (episodes/index.feature:48)
    ;;   | 2026-03-01-1000-ab12 | 2026-03-01-1006-s2x2 | gist | mini-embed | [4 411 114 101] |  (episodes/index.feature:49)
    ;;   | 2026-03-01-1000-ab12 | 2026-03-01-1006-s2x2 | text | mini-embed | [4 426 100 110] |  (episodes/index.feature:50)
    (g/with-step* "And the index for crew \"cordelia\" has rows:" "episodes/index.feature" 45 (fn [] (isaac.episodes.episode-steps/index-for-crew-has-rows "cordelia" {:headers ["episode-id" "scene-id" "kind" "model" "vector"], :rows [["2026-03-01-1000-ab12" "2026-03-01-1000-s1x1" "gist" "mini-embed" "[4 435 119 101]"] ["2026-03-01-1000-ab12" "2026-03-01-1000-s1x1" "text" "mini-embed" "[5 554 112 116]"] ["2026-03-01-1000-ab12" "2026-03-01-1006-s2x2" "gist" "mini-embed" "[4 411 114 101]"] ["2026-03-01-1000-ab12" "2026-03-01-1006-s2x2" "text" "mini-embed" "[4 426 100 110]"]], :header-line 46, :row-lines [47 48 49 50]}))))

